from collections import Counter
def f_all(gin, gout=None):
    bg = Counter(x for row in gin for x in row).most_common(1)[0][0]
    res = [[bg]*len(gin[0]) for _ in range(len(gin))]
    seeds = [(i,j,v) for i in range(len(gin)) for j in range(len(gin[0])) if gin[i][j]!=bg]
    h, w = len(gin), len(gin[0])
    for si, sj, v in seeds:
        if sj == 0:
            # horizontal stripes along the row, even columns = v
            for c in range(w): res[si][c] = v if c % 2 == 0 else bg
        else:
            # vertical line with arms: col at all rows, plus arms at odd-diff rows ±1
            col = sj
            for r in range(h):
                if (r - si) % 2 == 0:
                    res[r][col] = v
                else:
                    if col - 1 >= 0: res[r][col-1] = v
                    if col + 1 < w: res[r][col+1] = v
    return res

